import{_ as i,a0 as p,w as E,s as d,ao as l,I as a,x as t,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"EPEL-5 走向終點 | LCTT x X-CMD","titleTemplate":false,"description":"EPEL-5 走向終點 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"EPEL-5 走向終點 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"EPEL-5 走向終點 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170317 The End of the Line for EPEL-5","title":"EPEL-5 走向終點","tag":"201703","desc":""},"relativePath":"201703/20170317 The End of the Line for EPEL-5.md","filePath":"[post].md"}'),s={name:"201703/20170317 The End of the Line for EPEL-5.md"};function L(f,e,P,u,m,T){const o=p("Link");return E(),d("div",null,[e[19]||(e[19]=l('<h1 id="epel-5-走向終點" tabindex="-1">EPEL-5 走向終點 <a class="header-anchor" href="#epel-5-走向終點" aria-label="Permalink to “EPEL-5 走向終點”">​</a></h1><p><img src="https://cdn.fedoramagazine.org/wp-content/uploads/2017/03/epel5-eol-945x400.png" alt=""></p><p>在過去十年中，Fedora 項目一直都在為另外一個操作系統構建相同軟件包。<strong>然而，到 2017 年 3 月 31 日，它將會隨着 Red Hat Enterprise Linux（RHEL）5 一起停止這項工作</strong>。</p><h3 id="epel-的簡短歷史" tabindex="-1">EPEL 的簡短歷史 <a class="header-anchor" href="#epel-的簡短歷史" aria-label="Permalink to “EPEL 的簡短歷史”">​</a></h3><p>RHEL 是 Fedora 發佈版本的一個子集的下游重建版本，Red Hat 願為之支持好多年。雖然那些軟件包構成了完整的操作系統，但系統管理員一直都需要“更多”軟件包。在 RHEL-5 之前，許多那些軟件包會由不同的人打包並提供。隨着 Fedora Extras 逐漸包含了更多軟件包，並有幾位打包者加入了 Fedora，隨之出現了一個想法，結合力量並創建一個專門的子項目，重建特定於 RHEL 版本的 Fedora 軟件包，然後從 Fedora 的中心化服務器上分發。</p>',5)),a("p",null,[e[1]||(e[1]=t("經過多次討論，然而還是未能提出一個引人注目的名稱之後，Fedora 創建了子項目 Extra Packages for Enterprise Linux（簡稱 EPEL）。在首次為 RHEL-4 重建軟件包時，其主要目標是在 RHEL-5 發佈時提供儘可能多的用於 RHEL-5 的軟件包。打包者做了很多艱苦的工作，但大部分工作是在制定 EPEL 在未來十年的規則以及指導。",-1)),r(o,{href:"https://www.redhat.com/archives/epel-devel-list/2007-March/thread.html"},{default:n(()=>[...e[0]||(e[0]=[t("從所有人能夠看到的郵件歸檔中",-1)])]),_:1}),e[2]||(e[2]=t("我們可以看到 Fedora 貢獻者的激烈討論，它們擔心將 Fedora 的發佈重心轉移到外部貢獻者會與已經存在的軟件包產生衝突。",-1))]),e[20]||(e[20]=l('<p>最後，EPEL-5 在 2007 年 4 月的某個時候上線了，在接下來的十年中，它已經成長為一個擁有 5000 多個源碼包的倉庫，並且每天會有 20 萬個左右獨立 IP 地址檢查軟件包，並在 2013 年初達到 24 萬的高峯。雖然為 EPEL 構建的每個包都是使用 RHEL 軟件包完成的，但所有這些軟件包可以用於 RHEL 的各種社區重建版本（CentOS、Scientific Linux、Amazon Linux）。這意味着隨着這些生態系統的增長，給 EPEL 帶來了更多的用户，並在隨後的 RHEL 版本發佈時幫助打包。然而，隨着新版本以及重建版本的使用量越來越多，EPEL-5 的用户數量逐漸下降為每天大約 16 萬個獨立 IP 地址。此外，在此期間，開發人員支持的軟件包數量已經下降，倉庫大小已縮小到 2000 個源代碼包。</p><p>收縮的部分原因是由於 2007 年的原始規定。當時，Red Hat Enterprise Linux 被認為只有 6 年活躍的生命週期。有人認為，在這樣一個“有限”的週期中，軟件包可能就像在 RHEL 中那樣在 EPEL 中被“凍結”。這意味着無論何時有可能的修復需要向後移植，也不允許有主要的修改。因為沒有人來打包，軟件包將不斷從 EPEL-5 中移除，因為打包者不再想嘗試並向後移植。儘管各種規則被放寬以允許更大的更改，Fedora 使用的打包規則從 2007 年開始不斷地改變和改進。這使得在較舊的操作系統上嘗試重新打包一個較新的版本變得越來越難。</p><h3 id="_2017-年-3-月-31-日會發生什麼" tabindex="-1">2017 年 3 月 31 日會發生什麼 <a class="header-anchor" href="#_2017-年-3-月-31-日會發生什麼" aria-label="Permalink to “2017 年 3 月 31 日會發生什麼”">​</a></h3><p>如上所述，3 月 31 日，紅帽將終止 RHEL-5 的支持並不再為普通客户提供更新。這意味着 Fedora 和各種重建版本將開始各種歸檔流程。對於 EPEL 項目，這意味着我們將跟隨 Fedora 發行版每年發佈的步驟。</p><ol><li>在 ** 3 月 27 日**，任何新版本將不會被允許推送到 EPEL-5，以便倉庫本質上被凍結。這允許鏡像擁有一個清晰的文件樹。</li><li>EPEL-5 中的所有包將從主鏡像 <code>/pub/epel/5/</code> 以及 <code>/pub/epel/testing/5/</code> 移動到 <code>/pub/archives/epel/</code>。 **這將會在 27 號開始*，因此所有的歸檔鏡像站點可以用它寫入磁盤。</li><li>因為 3 月 31 日是星期五，系統管理員並不喜歡週五驚喜，所以它不會有變化。<strong>4 月 3 日</strong>，鏡像管理器將更新指向歸檔。</li><li><strong>4 月 6 日</strong>，<code>/pub/epel/5/</code> 樹將被刪除，鏡像也將相應更新。</li></ol><p>對於使用 cron 執行 yum 更新的系統管理員而言，這應該只是一個小麻煩。系統能繼續更新甚至安裝歸檔中的任何軟件包。那些直接使用腳本從鏡像下載的系統管理員會有點麻煩，需要將腳本更改到 <code>/pub/archive/epel/5/</code> 這個新的位置。</p><p>雖然令人討厭，但是對於仍使用舊版 Linux 的許多系統管理員也許算是好事吧。由於軟件包不斷地從 EPEL-5 中刪除，各種支持郵件列表以及 irc 頻道都有系統管理員驚奇他們需要的哪些軟件包消失到哪裏了。歸檔完成後，這將不會是一個問題，因為不會更多的包會被刪除了 😃。</p>',7)),a("p",null,[e[4]||(e[4]=t("對於受此問題影響的系統管理員，較舊的 EPEL 軟件包仍然可用，但速度較慢。所有 EPEL 軟件包都是在 Fedora Koji 系統中構建的，所以你可以使用 ",-1)),r(o,{href:"https://koji.fedoraproject.org/koji/search"},{default:n(()=>[...e[3]||(e[3]=[t("Koji 搜索",-1)])]),_:1}),e[5]||(e[5]=t("到較舊版本的軟件包。",-1))]),e[21]||(e[21]=a("hr",null,null,-1)),a("p",null,[e[7]||(e[7]=t("via: ",-1)),r(o,{href:"https://fedoramagazine.org/the-end-of-the-line-for-epel-5/"},{default:n(()=>[...e[6]||(e[6]=[t("https://fedoramagazine.org/the-end-of-the-line-for-epel-5/",-1)])]),_:1})]),a("p",null,[e[11]||(e[11]=t("作者：",-1)),r(o,{href:"http://smooge.id.fedoraproject.org/"},{default:n(()=>[...e[8]||(e[8]=[t("smooge",-1)])]),_:1}),e[12]||(e[12]=t(" 譯者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:n(()=>[...e[9]||(e[9]=[t("geekpi",-1)])]),_:1}),e[13]||(e[13]=t(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[16]||(e[16]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:n(()=>[...e[15]||(e[15]=[t("Linux中國",-1)])]),_:1}),e[18]||(e[18]=t(" 榮譽推出",-1))])])}const C=i(s,[["render",L]]);export{h as __pageData,C as default};
